from collections.abc import Hashable, Sequence
import gzip
from io import BytesIO, StringIO
import json
from pathlib import Path
import shutil
import subprocess
import sys
from typing import BinaryIO, TypeAlias, cast

import pytest

from polyfile.search import ACNode, MultiSequenceSearch, StartsWithMatcher, TrieNode


Pattern: TypeAlias = bytes | str | tuple[Hashable, ...]

