class _OneRead:
    def __init__(self, value: object) -> None:
        self.value = value

    def read(self, size: int) -> object:
        value = self.value
        self.value = b""
        return value


def _run_python(source: str) -> None:
    """Bound regressions that previously looped while traversing invalid graphs."""
    try:
        result = subprocess.run(
            [sys.executable, "-W", "error", "-c", source],
            capture_output=True,
            text=True,
            timeout=5,
        )
    except subprocess.TimeoutExpired:
        pytest.fail("Search operation exceeded the five-second test budget", pytrace=False)
    assert result.returncode == 0, result.stderr
    assert result.stderr == ""
    assert result.stdout == ""


def _expected(
    patterns: tuple[Pattern, ...], data: Sequence[Hashable]
) -> Counter[tuple[int, Pattern]]:
    symbols = tuple(data)
    matches: Counter[tuple[int, Pattern]] = Counter()
    for offset in range(len(symbols) + 1):
        for pattern in set(patterns):
            stop = offset + len(pattern)
            if symbols[offset:stop] == tuple(pattern):
                matches[(offset, pattern)] += 1
    return matches


@pytest.mark.parametrize("iterator_input", (False, True))
@pytest.mark.parametrize(
    ("patterns", "data"),
    (
        ((("word",), ("word", "token"), ("token",)), ("word", "token", "word")),
        (
            ((("red", 1),), (("red", 1), ("blue", 2))),
            (("red", 1), ("blue", 2), ("red", 1)),
        ),
        (((None,), (None, "word"), ("word", None)), (None, "word", None)),
    ),
)
def test_hashable_sequence_symbols_remain_atomic(
    patterns: tuple[Pattern, ...], data: tuple[Hashable, ...], iterator_input: bool
) -> None:
    source = iter(data) if iterator_input else data
    assert Counter(MultiSequenceSearch(*patterns).search(source)) == _expected(patterns, data)


@pytest.mark.parametrize("iterator_input", (False, True))
@pytest.mark.parametrize(
    ("patterns", "data"),
    (
        ((b"", b"a", b""), b"aba"),
        (("", "é", ""), "éxé"),
        (((), ("word",), ()), ("word", "token")),
        ((b"",), b""),
        (("",), ""),
        (((),), ()),
    ),
)
def test_empty_patterns_match_each_source_boundary(
    patterns: tuple[Pattern, ...], data: Sequence[Hashable], iterator_input: bool
) -> None:
    source = iter(data) if iterator_input else data
    assert Counter(MultiSequenceSearch(*patterns).search(source)) == _expected(patterns, data)


@pytest.mark.parametrize("text", (False, True))
@pytest.mark.parametrize("empty_input", (False, True))
def test_empty_patterns_include_binary_and_text_reader_boundaries(
    text: bool, empty_input: bool
) -> None:
    if text:
        data = "" if empty_input else "ééx"
        assert Counter(MultiSequenceSearch("", "é").search(StringIO(data))) == _expected(
            ("", "é"), data
        )
    else:
        data = b"" if empty_input else b"aax"
        assert Counter(MultiSequenceSearch(b"", b"a").search(BytesIO(data))) == _expected(
            (b"", b"a"), data
        )


@pytest.mark.parametrize("pattern", ([], [1, 2], ([1],), (object(), []), 42, None, frozenset({1})))
def test_unsupported_patterns_are_rejected(pattern: object) -> None:
    with pytest.raises(TypeError):
        MultiSequenceSearch(cast(Pattern, pattern))


@pytest.mark.parametrize(
    ("value", "error"),
    ((None, TypeError), (7, TypeError), (b"ab", ValueError), ("ab", ValueError)),
)
def test_invalid_reader_results_fail_with_read_context(
    value: object, error: type[Exception]
) -> None:
    reader = cast(BinaryIO, _OneRead(value))
    with pytest.raises(error, match="read"):
        list(MultiSequenceSearch(b"a").search(reader))


def test_trie_terminal_paths_and_prefixes_remain_distinct() -> None:
    tree = TrieNode()
    tree.add("alphabet")
    tree.add("alpine")
    assert "a" in tree
    assert "alp" not in tree
    assert not tree.find("alp")
    assert tree.find("alphabet")
    assert set(tree.find_prefix("alp")) == {"alphabet", "alpine"}
    assert list(tree.find_prefix("missing")) == []


def test_trie_word_symbols_support_terminal_and_prefix_lookup() -> None:
    tree = TrieNode()
    tree.add(("word", "token"), source="document")
    tree.add(("word", "other"), source="metadata")
    assert ("word",) in tree
    assert tree["word"].value == "word"
    assert tree.find(("word", "token"))
    assert not tree.find(("word",))
    assert set(tree.find_prefix(("word",))) == {"document", "metadata"}


def test_deep_trie_paths_and_representations_do_not_recurse() -> None:
    pattern = b"a" * (sys.getrecursionlimit() + 50) + b"b"
    tree = TrieNode()
    tree.add(pattern)
    tree.add(pattern + b"c")
    assert tree.find(pattern)
    assert not tree.find(pattern[:-1])
    assert set(tree.find_prefix(pattern[:-1])) == {pattern, pattern + b"c"}
    assert len(list(tree.bfs())) == len(pattern) + 2
    assert len(list(tree.dfs())) == len(pattern) + 2
    assert "TrieNode" in repr(tree)


def test_deep_search_round_trip_keeps_matches_and_links() -> None:
    _run_python("""
from io import BytesIO
import sys
from polyfile.search import MultiSequenceSearch
pattern = b'a' * (sys.getrecursionlimit() + 50) + b'b'
search = MultiSequenceSearch(pattern, b'ab', b'b')
output = BytesIO()
search.save(output)
output.seek(0)
restored = MultiSequenceSearch.load(output)
assert sorted(restored.search(pattern)) == sorted(search.search(pattern))
assert 'ACNode' in repr(restored.trie)
""")


@pytest.mark.parametrize("traversal", ("bfs", "dfs"))
def test_graph_traversals_visit_shared_and_cyclic_nodes_once(traversal: str) -> None:
    _run_python(f"""
from polyfile.search import TrieNode
root = TrieNode('root')
child = TrieNode('child')
equal_child = TrieNode('child')
root._children.update({{'first': child, 'second': child, 'equal': equal_child}})
child._children['cycle'] = root
nodes = list(root.{traversal}())
assert len(nodes) == 3
assert {{id(node) for node in nodes}} == {{id(root), id(child), id(equal_child)}}
""")


def test_finalizing_a_cyclic_trie_fails_without_hanging() -> None:
    _run_python("""
from polyfile.search import MultiSequenceSearch
search = MultiSequenceSearch(b'a')
search.trie[97]._children[97] = search.trie
try:
    search.trie.finalize()
except ValueError as error:
    assert str(error)
else:
    raise AssertionError('A cyclic search trie was accepted')
""")


@pytest.mark.parametrize("keyword_arguments", (False, True))
def test_constructor_preserves_parent_and_failure_arguments(keyword_arguments: bool) -> None:
    parent = ACNode()
    failure = ACNode()
    if keyword_arguments:
        node = ACNode(value=97, sources={b"a"}, parent=parent, _fall=failure)
    else:
        node = ACNode(97, {b"a"}, None, parent, failure)
    assert node.parent is parent
    assert node.fall is failure


def test_node_equality_preserves_value_comparisons() -> None:
    left = TrieNode("a")
    right = TrieNode("a")
    right.add("different subtree")
    assert left == right
    assert hash(left) == hash(right)
    assert left != TrieNode("b")
    assert left != "a"
    assert left != object()


def test_frozen_five_field_root_loads_and_rebuilds_links() -> None:
    _run_python(f"""
from io import BytesIO
from polyfile.search import MultiSequenceSearch
stream = BytesIO(bytes.fromhex({LEGACY_ROOT!r}))
search = MultiSequenceSearch.load(stream)
assert not stream.closed
assert list(search.search(b'aba')) == [(0, b'a'), (2, b'a')]
assert search.trie.fall is search.trie
assert search.trie[97].parent is search.trie
assert search.trie[97].fall is search.trie
""")


@pytest.mark.parametrize("encoded", INVALID_ROOTS.values(), ids=INVALID_ROOTS.keys())
def test_malformed_serialized_tries_fail_clearly(encoded: str) -> None:
    _run_python(f"""
from io import BytesIO
from polyfile import serialization
from polyfile.search import MultiSequenceSearch
try:
    MultiSequenceSearch.load(BytesIO(bytes.fromhex({encoded!r})))
except (ValueError, serialization.EncodingError) as error:
    assert str(error)
else:
    raise AssertionError('A malformed search trie was accepted')
""")


def test_repeated_gzip_file_saves_preserve_the_live_search(tmp_path: Path) -> None:
    search = MultiSequenceSearch(b"he", b"she", b"his", b"hers")
    nodes = [cast(ACNode, node) for node in search.trie.bfs()]
    original = [(node, node.parent, node.fall) for node in nodes]
    expected = list(search.search(b"ushershishe"))
    for repeat in range(2):
        path = tmp_path / f"search-{repeat}.gz"
        with gzip.open(path, "wb") as output:
            search.save(output)
        with gzip.open(path, "rb") as source:
            loaded = MultiSequenceSearch.load(source)
        assert Counter(loaded.search(b"ushershishe")) == Counter(expected)
        for node, parent, failure in original:
            assert node.parent is parent
            assert node.fall is failure
        assert list(search.search(b"ushershishe")) == expected


@pytest.mark.parametrize("pattern", (b'\x00a"\\', 'é\n"\\', (None, ("red", 1), '"\\')))
def test_dot_accepts_all_supported_symbol_families(pattern: Pattern) -> None:
    assert "digraph" in MultiSequenceSearch(pattern).trie.to_dot(include_falls=True)


@pytest.mark.skipif(shutil.which("dot") is None, reason="Graphviz dot is not installed")
@pytest.mark.parametrize("subtree", (False, True))
@pytest.mark.parametrize("include_falls", (False, True))
def test_dot_only_references_nodes_in_the_rendered_trie(subtree: bool, include_falls: bool) -> None:
    root = MultiSequenceSearch((None, ("red", 1), '"\\')).trie
    node = root[None] if subtree else root
    source = node.to_dot(include_falls=include_falls)
    result = subprocess.run(
        ["dot", "-Tjson"], input=source, capture_output=True, text=True, check=True, timeout=5
    )
    assert result.stderr == ""
    rendered = json.loads(result.stdout)
    assert len(rendered["objects"]) == len(list(node.bfs()))
    if not subtree:
        assert sum(item["label"] == "Root" for item in rendered["objects"]) == 1


def test_prefix_matcher_handles_multiword_symbols() -> None:
    patterns = (("word",), ("word", "token"), ())
    assert Counter(StartsWithMatcher(*patterns).search(iter(("word", "token")))) == Counter(
        (0, pattern) for pattern in patterns
    )


def test_nonreflexive_symbols_follow_dictionary_identity_semantics() -> None:
    symbol = float("nan")
    pattern = (symbol,)
    search = MultiSequenceSearch(pattern)
    result = list(search.search(pattern))
    assert len(result) == 1
    assert result[0][0] == 0
    assert result[0][1] is pattern
    assert list(StartsWithMatcher(pattern).search(pattern)) == [(0, pattern)]


def test_registered_nonreflexive_symbols_survive_round_trips() -> None:
    _run_python("""
from io import BytesIO
from polyfile import serialization
from polyfile.search import MultiSequenceSearch

@serialization.serializable
class Symbol:
    def __init__(self, value):
        self.value = value
    def __hash__(self):
        return hash(self.value)
    def __eq__(self, other):
        return False
    def serialize(self):
        return (self.value,)

search = MultiSequenceSearch((Symbol('word'),))
stream = BytesIO()
search.save(stream)
stream.seek(0)
restored = MultiSequenceSearch.load(stream)
terminal = next(iter(restored.trie))
pattern = next(iter(terminal.sources))
result = list(restored.search(pattern))
assert len(result) == 1 and result[0][0] == 0
assert result[0][1] is pattern
""")
